//! display/dc/inc/hw/opp.h + opp/dcn20/dcn20_opp.{h,c} (Linux 6.18.55), with the
//! `opp_regs`/`opp_shift`/`opp_mask` table of dcn21_resource.c: the output pixel
//! processor (OPP) of Renoir's resource pool. Renoir reuses the dcn20 OPP.
//!
//! `dcn21_opp_create` → `dcn20_opp_construct` stores the instance, funcs and the
//! register pointers. The ops of dcn20_opp.c are ported as the hw sequencer
//! reaches them. The register tables are machine-generated by
//! `dcgen.py` from `OPP_REG_LIST_DCN20` / `OPP_MASK_SH_LIST_DCN20`. The static
//! array is `opp_regs[6]` (used 0..3 on Renoir), so the table carries 6 pipes.
#![allow(dead_code)]

use crate::amdgpu_device::amdgpu_device;
use crate::dc_helper::{reg_get, reg_get_n, reg_set, reg_update, reg_write};
use crate::dc_types::MAX_PIPES;
use crate::dcn20_mpc::mpc_tree;
use crate::regs::*;
use alloc::boxed::Box;

/// Which `opp_funcs` vtable `output_pixel_processor.funcs` points at
/// (dcn20_opp.c).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum opp_funcs {
    dcn20_opp_funcs,
}

/// `struct tg_color` (dc_hw_types.h): at most 10 bits per component.
#[derive(Default, Clone, Copy, PartialEq, Eq, Debug)]
pub struct tg_color {
    pub color_r_cr: u16,
    pub color_g_y: u16,
    pub color_b_cb: u16,
}

/// `struct opp_funcs` (opp.h), the members ported. `None` is a member the
/// port has not reached.
#[derive(Default, Clone, Copy)]
pub struct opp_ops {
    pub opp_set_disp_pattern_generator: Option<fn(&amdgpu_device, &dcn20_opp, u32, u32, u32, &tg_color, i32, i32, i32)>,
    pub dpg_is_blanked: Option<fn(&amdgpu_device, &dcn20_opp) -> bool>,
    pub dpg_is_pending: Option<fn(&amdgpu_device, &dcn20_opp) -> bool>,
}

/// `dcn20_opp_funcs` (dcn20_opp.c), as far as ported.
const DCN20_OPP_FUNCS: opp_ops = opp_ops {
    opp_set_disp_pattern_generator: Some(opp2_set_disp_pattern_generator),
    dpg_is_blanked: Some(opp2_dpg_is_blanked),
    dpg_is_pending: Some(opp2_dpg_is_pending),
};

impl opp_funcs {
    pub fn ops(self) -> &'static opp_ops {
        match self {
            opp_funcs::dcn20_opp_funcs => &DCN20_OPP_FUNCS,
        }
    }
}

/// `struct output_pixel_processor` (inc/hw/opp.h): the base object. Linux' `ctx`
/// is not stored (see `clock_source`); the regamma and dyn_expansion state
/// joins grow-as-reached.
#[derive(Default)]
pub struct output_pixel_processor {
    pub inst: u32,
    pub funcs: Option<opp_funcs>,
    pub mpc_tree_params: mpc_tree,
    pub mpcc_disconnect_pending: [bool; MAX_PIPES],
}

/// `struct dcn20_opp` (dcn20_opp.h): the concrete OPP.
#[derive(Default)]
pub struct dcn20_opp {
    pub base: output_pixel_processor,
    pub regs: Option<&'static dcn20_opp_registers>,
    pub opp_shift: Option<&'static dcn20_opp_shift>,
    pub opp_mask: Option<&'static dcn20_opp_mask>,
    pub is_write_to_ram_a_safe: bool,
}

impl dcn20_opp {
    /// `opp->funcs`.
    pub fn funcs(&self) -> &'static opp_ops {
        self.base.funcs.expect("opp funcs").ops()
    }

    fn rsm(&self) -> (&'static dcn20_opp_registers, &'static dcn20_opp_shift, &'static dcn20_opp_mask) {
        (self.regs.unwrap(), self.opp_shift.unwrap(), self.opp_mask.unwrap())
    }
}

/// `opp2_set_disp_pattern_generator` (dcn20_opp.c). The enums are their values.
#[allow(clippy::too_many_arguments)]
pub fn opp2_set_disp_pattern_generator(adev: &amdgpu_device, oppn20: &dcn20_opp, test_pattern: u32, color_space: u32,
                                       color_depth: u32, solid_color: &tg_color, width: i32, height: i32,
                                       offset: i32) {
    // color ramp generator mixes 16-bits color
    let src_bpc: u32 = 16;
    // RGB values of the color bars: RGB0 white (all Fs), RGB1 black (all 0s)
    let src_color: [u16; 6] = [0xFFFF, 0xFFFF, 0xFFFF, 0x0000, 0x0000, 0x0000];
    let mut dst_color = [0u16; 6];
    let c = oppn20.rsm();

    // translate to bit depth
    let bit_depth = match color_depth {
        COLOR_DEPTH_666 => TEST_PATTERN_COLOR_FORMAT_BPC_6,
        COLOR_DEPTH_888 => TEST_PATTERN_COLOR_FORMAT_BPC_8,
        COLOR_DEPTH_101010 => TEST_PATTERN_COLOR_FORMAT_BPC_10,
        COLOR_DEPTH_121212 => TEST_PATTERN_COLOR_FORMAT_BPC_12,
        _ => TEST_PATTERN_COLOR_FORMAT_BPC_8,
    };

    // set DPG dimentions
    reg_set!(adev, c, DPG_DIMENSIONS, 0, DPG_ACTIVE_WIDTH, width, DPG_ACTIVE_HEIGHT, height);

    // set DPG offset
    reg_set!(adev, c, DPG_OFFSET_SEGMENT, 0, DPG_X_OFFSET, offset, DPG_SEGMENT_WIDTH, 0);

    match test_pattern {
        CONTROLLER_DP_TEST_PATTERN_COLORSQUARES | CONTROLLER_DP_TEST_PATTERN_COLORSQUARES_CEA => {
            let dyn_range = if test_pattern == CONTROLLER_DP_TEST_PATTERN_COLORSQUARES_CEA {
                TEST_PATTERN_DYN_RANGE_CEA
            } else {
                TEST_PATTERN_DYN_RANGE_VESA
            };

            let mode = match color_space {
                CONTROLLER_DP_COLOR_SPACE_YCBCR601 => TEST_PATTERN_MODE_COLORSQUARES_YCBCR601,
                CONTROLLER_DP_COLOR_SPACE_YCBCR709 => TEST_PATTERN_MODE_COLORSQUARES_YCBCR709,
                _ => TEST_PATTERN_MODE_COLORSQUARES_RGB,
            };

            reg_update!(adev, c, DPG_CONTROL, DPG_EN, 1, DPG_MODE, mode, DPG_DYNAMIC_RANGE, dyn_range,
                DPG_BIT_DEPTH, bit_depth, DPG_VRES, 6, DPG_HRES, 6);
        }
        CONTROLLER_DP_TEST_PATTERN_VERTICALBARS | CONTROLLER_DP_TEST_PATTERN_HORIZONTALBARS => {
            let mode = if test_pattern == CONTROLLER_DP_TEST_PATTERN_VERTICALBARS {
                TEST_PATTERN_MODE_VERTICALBARS
            } else {
                TEST_PATTERN_MODE_HORIZONTALBARS
            };

            let dst_bpc: u32 = match bit_depth {
                TEST_PATTERN_COLOR_FORMAT_BPC_6 => 6,
                TEST_PATTERN_COLOR_FORMAT_BPC_8 => 8,
                TEST_PATTERN_COLOR_FORMAT_BPC_10 => 10,
                _ => 8,
            };

            // adjust color to the required colorFormat
            for index in 0..6 {
                // dst = 2^dstBpc * src / 2^srcBpc = src >> (srcBpc - dstBpc);
                dst_color[index] = src_color[index] >> (src_bpc - dst_bpc);
                // DPG_COLOUR registers are 16-bit MSB aligned value with bits 3:0 hardwired to ZERO.
                dst_color[index] <<= 16 - dst_bpc;
            }

            reg_set!(adev, c, DPG_COLOUR_R_CR, 0, DPG_COLOUR1_R_CR, dst_color[0], DPG_COLOUR0_R_CR, dst_color[3]);
            reg_set!(adev, c, DPG_COLOUR_G_Y, 0, DPG_COLOUR1_G_Y, dst_color[1], DPG_COLOUR0_G_Y, dst_color[4]);
            reg_set!(adev, c, DPG_COLOUR_B_CB, 0, DPG_COLOUR1_B_CB, dst_color[2], DPG_COLOUR0_B_CB, dst_color[5]);

            // enable test pattern
            reg_update!(adev, c, DPG_CONTROL, DPG_EN, 1, DPG_MODE, mode, DPG_DYNAMIC_RANGE, 0, DPG_BIT_DEPTH, bit_depth,
                DPG_VRES, 0, DPG_HRES, 0);
        }
        CONTROLLER_DP_TEST_PATTERN_COLORRAMP => {
            let mode = if bit_depth == TEST_PATTERN_COLOR_FORMAT_BPC_10 {
                TEST_PATTERN_MODE_DUALRAMP_RGB
            } else {
                TEST_PATTERN_MODE_SINGLERAMP_RGB
            };

            let dst_bpc: u32 = match bit_depth {
                TEST_PATTERN_COLOR_FORMAT_BPC_6 => 6,
                TEST_PATTERN_COLOR_FORMAT_BPC_8 => 8,
                TEST_PATTERN_COLOR_FORMAT_BPC_10 => 10,
                _ => 8,
            };

            // increment for the first ramp for one color gradation;
            // 1 gradation for 6-bit color is 2^10 gradations in 16-bit color
            let inc_base = src_bpc - dst_bpc;

            match bit_depth {
                TEST_PATTERN_COLOR_FORMAT_BPC_6 => {
                    reg_set!(adev, c, DPG_RAMP_CONTROL, 0, DPG_RAMP0_OFFSET, 0, DPG_INC0, inc_base, DPG_INC1, 0);
                    reg_update!(adev, c, DPG_CONTROL, DPG_VRES, 6, DPG_HRES, 6);
                }
                TEST_PATTERN_COLOR_FORMAT_BPC_8 => {
                    reg_set!(adev, c, DPG_RAMP_CONTROL, 0, DPG_RAMP0_OFFSET, 0, DPG_INC0, inc_base, DPG_INC1, 0);
                    reg_update!(adev, c, DPG_CONTROL, DPG_VRES, 6, DPG_HRES, 8);
                }
                TEST_PATTERN_COLOR_FORMAT_BPC_10 => {
                    reg_set!(adev, c, DPG_RAMP_CONTROL, 0, DPG_RAMP0_OFFSET, 384 << 6, DPG_INC0, inc_base,
                        DPG_INC1, inc_base + 2);
                    reg_update!(adev, c, DPG_CONTROL, DPG_VRES, 5, DPG_HRES, 8);
                }
                _ => {}
            }

            // enable test pattern
            reg_update!(adev, c, DPG_CONTROL, DPG_EN, 1, DPG_MODE, mode, DPG_DYNAMIC_RANGE, 0, DPG_BIT_DEPTH, bit_depth);
        }
        CONTROLLER_DP_TEST_PATTERN_VIDEOMODE => {
            reg_write!(adev, c.0, DPG_CONTROL, 0);
            reg_write!(adev, c.0, DPG_COLOUR_R_CR, 0);
            reg_write!(adev, c.0, DPG_COLOUR_G_Y, 0);
            reg_write!(adev, c.0, DPG_COLOUR_B_CB, 0);
            reg_write!(adev, c.0, DPG_RAMP_CONTROL, 0);
        }
        CONTROLLER_DP_TEST_PATTERN_SOLID_COLOR => {
            opp2_dpg_set_blank_color(adev, oppn20, solid_color);
            reg_update!(adev, c, DPG_CONTROL, DPG_EN, 1, DPG_MODE, TEST_PATTERN_MODE_HORIZONTALBARS);

            reg_set!(adev, c, DPG_DIMENSIONS, 0, DPG_ACTIVE_WIDTH, width, DPG_ACTIVE_HEIGHT, height);
        }
        _ => {}
    }
}

/// `opp2_dpg_set_blank_color` (dcn20_opp.c): 16-bit MSB aligned values; bits
/// 3:0 of the fields are hardwired to zero.
pub fn opp2_dpg_set_blank_color(adev: &amdgpu_device, oppn20: &dcn20_opp, color: &tg_color) {
    let c = oppn20.rsm();
    reg_set!(adev, c, DPG_COLOUR_B_CB, 0, DPG_COLOUR1_B_CB, (color.color_b_cb as u32) << 6,
        DPG_COLOUR0_B_CB, (color.color_b_cb as u32) << 6);
    reg_set!(adev, c, DPG_COLOUR_G_Y, 0, DPG_COLOUR1_G_Y, (color.color_g_y as u32) << 6,
        DPG_COLOUR0_G_Y, (color.color_g_y as u32) << 6);
    reg_set!(adev, c, DPG_COLOUR_R_CR, 0, DPG_COLOUR1_R_CR, (color.color_r_cr as u32) << 6,
        DPG_COLOUR0_R_CR, (color.color_r_cr as u32) << 6);
}

/// `opp2_dpg_is_blanked` (dcn20_opp.c).
pub fn opp2_dpg_is_blanked(adev: &amdgpu_device, oppn20: &dcn20_opp) -> bool {
    let [dpg_en, _dpg_mode] = reg_get_n!(adev, oppn20.rsm(), DPG_CONTROL, DPG_EN, DPG_MODE);
    let double_buffer_pending = reg_get!(adev, oppn20.rsm(), DPG_STATUS, DPG_DOUBLE_BUFFER_PENDING);
    dpg_en == 1 && double_buffer_pending == 0
}

/// `opp2_dpg_is_pending` (dcn20_opp.c).
pub fn opp2_dpg_is_pending(adev: &amdgpu_device, oppn20: &dcn20_opp) -> bool {
    let dpg_en = reg_get!(adev, oppn20.rsm(), DPG_CONTROL, DPG_EN);
    let double_buffer_pending = reg_get!(adev, oppn20.rsm(), DPG_STATUS, DPG_DOUBLE_BUFFER_PENDING);
    dpg_en == 1 && double_buffer_pending == 1
}

/// `dcn20_opp_construct` (dcn20_opp.c): store the instance, funcs and registers.
pub fn dcn20_opp_construct(
    opp: &mut dcn20_opp,
    inst: u32,
    regs: &'static dcn20_opp_registers,
    opp_shift: &'static dcn20_opp_shift,
    opp_mask: &'static dcn20_opp_mask,
) {
    opp.base.inst = inst;
    opp.base.funcs = Some(opp_funcs::dcn20_opp_funcs);
    opp.regs = Some(regs);
    opp.opp_shift = Some(opp_shift);
    opp.opp_mask = Some(opp_mask);
}

/// `dcn21_opp_create` (dcn21_resource.c): allocate a `dcn20_opp` for pipe `inst`
/// and construct it.
pub fn dcn21_opp_create(inst: u32) -> Box<dcn20_opp> {
    let mut opp = Box::new(dcn20_opp::default());
    dcn20_opp_construct(&mut opp, inst, &OPP_REGS[inst as usize], &OPP_SHIFT, &OPP_MASK);
    opp
}

